import {cabinet,rect,circle,text,ring,line,clamp,colors,pick} from './cabinet.js';
export const bubblePoint=(r,c)=>({x:36+c*36+(r%2)*18,y:60+r*31.2});
export function bubbleNeighbors(r,c){const p=bubblePoint(r,c),out=[];for(let rr=Math.max(0,r-1);rr<=Math.min(9,r+1);rr++)for(let cc=Math.max(0,c-1);cc<=Math.min(7,c+1);cc++){const n=bubblePoint(rr,cc);if((rr!==r||cc!==c)&&Math.hypot(n.x-p.x,n.y-p.y)<37)out.push([rr,cc]);}return out;}
export function bubbleCluster(board,r,c,same=true){const color=board[r]?.[c];if(!color)return [];const seen=new Set(),todo=[[r,c]],out=[];while(todo.length){const [rr,cc]=todo.pop(),k=rr*8+cc;if(seen.has(k)||!board[rr]?.[cc]||(same&&board[rr][cc]!==color))continue;seen.add(k);out.push([rr,cc]);todo.push(...bubbleNeighbors(rr,cc));}return out;}
export function floatingBubbles(board){const attached=new Set();for(let c=0;c<8;c++)for(const [r,cc] of bubbleCluster(board,0,c,false))attached.add(r*8+cc);const out=[];board.forEach((row,r)=>row.forEach((v,c)=>{if(v&&!attached.has(r*8+c))out.push([r,c]);}));return out;}
export function createBubbles(mount,api){const q=cabinet(mount,api,{accent:'#b9acff'}),c=q.c;let board,ammo=1,next=2,angle=-Math.PI/2,ball=null,misses=0,aiming=false;
 const available=()=>[...new Set(board.flat().filter(Boolean))];
 function reset(){board=Array.from({length:10},(_,r)=>Array.from({length:8},()=>r<4?pick([1,2,3,4]):0));ammo=pick(available());next=pick(available());ball=null;angle=-Math.PI/2;misses=0;aiming=false;}
 function aim(p){angle=clamp(Math.atan2(p.y-418,p.x-180),-Math.PI+.2,-.2);}
 function shoot(){if(!q.active||ball)return;ball={x:180,y:418,vx:Math.cos(angle)*470,vy:Math.sin(angle)*470,color:ammo};q.sound('shoot');aiming=false;}
 function land(hit){let candidates=[];if(hit)candidates=bubbleNeighbors(hit.r,hit.col).filter(([r,col])=>!board[r][col]);else candidates=Array.from({length:8},(_,col)=>[0,col]).filter(([r,col])=>!board[r][col]);if(!candidates.length){ball=null;q.finish('No more breathing room.',`${q.score} points. Look for hanging clusters.`);return;}
  candidates.sort((a,b)=>{const aa=bubblePoint(...a),bb=bubblePoint(...b);return Math.hypot(aa.x-ball.x,aa.y-ball.y)-Math.hypot(bb.x-ball.x,bb.y-ball.y);});const [r,col]=candidates[0];board[r][col]=ball.color;ball=null;const group=bubbleCluster(board,r,col);if(group.length>=3){const pop=group;for(const [rr,cc] of pop)board[rr][cc]=0;const hanging=floatingBubbles(board);for(const [rr,cc] of hanging)board[rr][cc]=0;for(const [rr,cc] of [...pop,...hanging]){const p=bubblePoint(rr,cc);q.burst(p.x,p.y,colors[(ammo-1)%6],4);}q.add(pop.length*10+hanging.length*20);q.sound(hanging.length?'cascade':'pop',Math.min(group.length,8));q.say(hanging.length?`${hanging.length} DROPPED!`:`${group.length} BUBBLES POPPED`);misses=0;}else{misses++;q.sound('stick');}
  if(!available().length){q.finish('Clear skies.',`Every bubble cleared. ${q.score} points.`,true);return;}
  if(misses===5){if(board[9].some(Boolean)){q.finish('The ceiling caught up.',`${q.score} points. Match three to hold it back.`);return;}board.pop();board.unshift(Array.from({length:8},()=>pick(available())));misses=0;q.say('CEILING DESCENDING');q.sound('warning');}
  if(board[9].some(Boolean)){q.finish('Bubble trouble.',`${q.score} points. Bounce shots off the walls.`);return;}ammo=available().includes(next)?next:pick(available());next=pick(available());
 }
 reset();return {start(){reset();q.start();},pointerDown(p){aiming=true;aim(q.local(p));},pointerMove(p){if(aiming)aim(q.local(p));},pointerUp(p){if(aiming){aim(q.local(p));shoot();}},cancel(){aiming=false;},direction(d){if(!ball)angle=clamp(angle+(d==='left'?-.075:d==='right'?.075:0),-Math.PI+.2,-.2);},action:shoot,tick(dt){q.frame(dt,dt=>{if(!ball)return;for(let n=0;n<3&&ball;n++){ball.x+=ball.vx*dt/3;ball.y+=ball.vy*dt/3;if(ball.x<20){ball.x=40-ball.x;ball.vx=Math.abs(ball.vx);q.sound('wall');}if(ball.x>340){ball.x=680-ball.x;ball.vx=-Math.abs(ball.vx);q.sound('wall');}let hit=null;for(let r=0;r<10&&!hit;r++)for(let col=0;col<8;col++){if(!board[r][col])continue;const p=bubblePoint(r,col);if(Math.hypot(p.x-ball.x,p.y-ball.y)<34){hit={r,col};break;}}if(hit)land(hit);else if(ball.y<=60)land(null);}},()=>{q.header('MATCH 3 · DROP CLUSTERS',`${5-misses} UNTIL DROP`);line(c,16,352,344,352,'#ff8eac66',1);board.forEach((row,r)=>row.forEach((v,col)=>{if(v){const p=bubblePoint(r,col);circle(c,p.x,p.y+2,17,'#0b112b');circle(c,p.x,p.y,16,colors[v-1]);circle(c,p.x-5,p.y-5,4,'#ffffff55');text(c,v,p.x,p.y+1,14,'#192d42',700);}}));if(!ball){for(let n=1;n<18;n++){let x=180+Math.cos(angle)*n*12;while(x<20||x>340)x=x<20?40-x:680-x;circle(c,x,418+Math.sin(angle)*n*12,1.7,'#ddd2ff88');}}const p=ball||{x:180,y:418,color:ammo};circle(c,p.x,p.y,17,colors[p.color-1]);text(c,p.color,p.x,p.y,14,'#192d42',700);circle(c,290,418,13,colors[next-1]);text(c,next,290,418,12,'#192d42',700);text(c,'NEXT',290,446,12,'#a8b8d0');q.footer('Aim, release. Walls are your friends.');});},destroy:q.destroy};}
